DROP TABLE IF EXISTS `rate_honor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rate_honor` (
  `id` bigint(20) unsigned NOT NULL,
  `kegiatan_id` bigint(20) unsigned DEFAULT NULL,
  `posisi` varchar(255) NOT NULL,
  `jenis_kegiatan` enum('sensus','survei') DEFAULT NULL,
  `jenis_penugasan` enum('pcl_ppl','pml','pengolahan','pengawas_pengolahan') NOT NULL DEFAULT 'pcl_ppl',
  `status_kepegawaian` enum('organik','non_organik') NOT NULL DEFAULT 'non_organik' COMMENT 'Status kepegawaian: organik (PNS/PPPK) atau non organik',
  `deskripsi` text DEFAULT NULL,
  `satuan_id` bigint(20) unsigned NOT NULL,
  `satuan_listing_id` bigint(20) unsigned DEFAULT NULL,
  `rate` decimal(15,0) NOT NULL,
  `rate_listing` decimal(12,2) DEFAULT NULL,
  `tahun_berlaku` int(11) NOT NULL,
  `status` enum('aktif','nonaktif') NOT NULL DEFAULT 'aktif',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
